select ws.shipment_wrh as warehouseCode,ws.shipment_stock_code as stockCode,wsd.wholesale_shipment_id,wsd.goods_code, wsd.audit_quantity,wsd.apply_quantity,wsd.line,wsd.vendor_code,ws.order_priority from ord_wholesale_shipment ws left join ord_wholesale_shipment_detail wsd on wsd.wholesale_shipment_id = ws.id where ws.distribution_type = 'transfer' and ws.shipment_status = 'approved' and ws.id in
#{item}
and ws.pur_batch_number is null and wsd.purchase_no is null and ws.push_pur_progress = 1 and ws.push_pur_time is null and ws.biz_org_code = #{bizOrgCode} and ws.is_delete = 0 and wsd.is_delete = 0

SELECT IFNULL(sum(apply_quantity),0) as totalApplyQuantity, IFNULL(sum(apply_amount),0) as totalApplyAmount, IFNULL(sum(audit_quantity),0) as totalAuditQuantity, IFNULL(sum(audit_amount),0) as totalAuditAmount, IFNULL(sum(shipment_quantity),0) as totalShipmentQuantity, IFNULL(sum(practical_shipment_amount),0) as totalPracticalShipmentAmount FROM ord_wholesale_shipment_detail where wholesale_shipment_id in
#{wholesaleShipmentId}
and is_delete = 0

