update ord_wholesale_shipment_detail set

    audit_quantity = #{item.auditQuantity},


    audit_amount = #{item.auditAmount},

update_time = #{item.updateTime},updater = #{item.updater}
where id = #{item.id}

mapper.update:
update ord_wholesale_shipment_detail wsd left join ord_wholesale_shipment ws on ws.id = wsd.wholesale_shipment_id
    set wsd.purchase_no = #{obj.purchaseOrderNo},wsd.updater = #{updater},wsd.update_time = #{updateTime}
where wsd.vendor_code = #{obj.vendorCode} and ws.pur_batch_number = #{obj.purBatchNumber} and ws.biz_org_code = #{obj.bizOrgCode} and wsd.is_delete = 0 and ws.is_delete = 0

